     "name": "Playful Illustration Theme",
     "sample": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Interactive Creative 404 Page — Playful Illustration Theme</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}:root{--bg:#fff4d6;--fg:#26204a;--muted:#7a6f9b;--card:#ffffff;--line:#26204a;--ac:#7c4dff;--ac2:#ff6fb1;--on:#fff;--r:20px;--font:'Trebuchet MS','Segoe UI',system-ui,sans-serif}body{font-family:var(--font);background:var(--bg);color:var(--fg);line-height:1.55}h1,h2,h3,h4{font-weight:900;letter-spacing:-.02em}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit;color:inherit}img{max-width:100%}\nbody{min-height:100vh;display:grid;place-items:center;text-align:center;padding:24px;overflow:hidden}\n.n{font-size:clamp(5rem,22vw,11rem);font-weight:900;line-height:1;letter-spacing:-.05em;color:var(--ac)}\n.face{display:inline-block;width:.62em;height:.62em;border-radius:50%;background:var(--ac2);position:relative;vertical-align:middle;margin:0 -.02em}\n.face::before,.face::after{content:\"\";position:absolute;top:34%;width:14%;height:14%;border-radius:50%;background:var(--fg)}.face::before{left:28%}.face::after{right:28%}\n.face i{position:absolute;left:30%;right:30%;bottom:22%;height:12%;border-bottom:.07em solid var(--fg);border-radius:0 0 50% 50%;transform:rotate(180deg)}\nh1{font-size:1.9rem;margin:8px 0}p{color:var(--muted);max-width:420px;margin:0 auto 24px}.btn{display:inline-block;background:var(--ac);color:var(--on);padding:14px 30px;border-radius:99px;font-weight:800;border:3px solid var(--fg)}\n</style>\n</head>\n<body>\n<div><div class=\"n\">4<span class=\"face\"><i></i></span>4</div><h1>Oops! This page took a day off.</h1><p>The page you are looking for moved, was deleted, or never existed.</p><a class=\"btn\" href=\"/\">Take me home</a></div>\n</body>\n</html>\n"
