     "sample": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Launching Page with JavaScript Countdown — Vibrant Startup Abstract</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}:root{--bg:#fff7e6;--fg:#1a1233;--muted:#6b6280;--card:#ffffff;--line:#1a1233;--ac:#ff5a1f;--ac2:#ffcd00;--on:#fff;--r:18px;--font:'Trebuchet MS','Segoe UI',system-ui,sans-serif}body{font-family:var(--font);background:var(--bg);color:var(--fg);line-height:1.55}h1,h2,h3,h4{font-weight:800;letter-spacing:-.02em}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit;color:inherit}img{max-width:100%}\nbody{min-height:100vh;display:grid;place-items:center;text-align:center;padding:30px 20px}\n.w{max-width:680px;width:100%}.tag{display:inline-block;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ac);margin-bottom:18px}\nh1{font-size:clamp(2.2rem,6vw,3.6rem);line-height:1.08;margin-bottom:12px}p.s{color:var(--muted);margin-bottom:30px}\n.cd{display:flex;gap:12px;justify-content:center;margin-bottom:30px}.u{min-width:80px;padding:16px 8px;background:var(--card);border:1px solid var(--line);border-radius:var(--r)}\n.u b{display:block;font-size:2.2rem;line-height:1;font-variant-numeric:tabular-nums}.u span{font-size:.72rem;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}\nform{display:flex;gap:8px;max-width:440px;margin:0 auto}form input{flex:1;min-width:0;padding:14px 16px;border-radius:99px;border:1px solid var(--line);background:var(--card);outline:0}\nform button{border:0;border-radius:99px;padding:0 24px;background:var(--ac);color:var(--on);font-weight:700;cursor:pointer}.msg{min-height:24px;margin-top:12px;font-size:.9rem;color:var(--ac)}\nbody{background:linear-gradient(135deg,#ff5a1f,#ffcd00 60%,#ff6fb1)}.u{background:rgba(255,255,255,.7)}\n</style>\n</head>\n<body>\n<div class=\"w\"><span class=\"tag\">Launching soon</span><h1>Something great is almost here.</h1><p class=\"s\">Be the first to know when we open the doors.</p>\n<div class=\"cd\"><div class=\"u\"><b id=\"d\">00</b><span>Days</span></div><div class=\"u\"><b id=\"h\">00</b><span>Hours</span></div><div class=\"u\"><b id=\"m\">00</b><span>Minutes</span></div><div class=\"u\"><b id=\"s\">00</b><span>Seconds</span></div></div>\n<form id=\"f\" novalidate><input id=\"e\" type=\"email\" placeholder=\"Your email address\" aria-label=\"Email\"><button>Notify me</button></form><div class=\"msg\" id=\"msg\"></div></div>\n<script>\nvar T=new Date(Date.now()+30*864e5);/* ← set your launch date here, e.g. new Date('2026-12-01T09:00:00') */\nfunction p(n){return n<10?'0'+n:n}\nfunction tick(){var x=Math.max(0,T-Date.now()),s=Math.floor(x/1000);document.getElementById('d').textContent=p(Math.floor(s/86400));document.getElementById('h').textContent=p(Math.floor(s%86400/3600));document.getElementById('m').textContent=p(Math.floor(s%3600/60));document.getElementById('s').textContent=p(s%60)}\ntick();setInterval(tick,1000);\ndocument.getElementById('f').onsubmit=function(e){e.preventDefault();document.getElementById('msg').textContent='Thanks!'};\n</script>\n</body>\n</html>\n"
